"""A product introduction and an explicitly graded public interview evidence register."""
import json
from build_final_project_workshop import icon


def build_intro(root, twin, p, ul):
    evidence = json.loads((root/'final-project/interview-evidence.json').read_text())
    def link(href, fa, en):
        return f'<a class="workshop-link" href="{href}">'+twin(fa,en)+icon('next')+'</a>'

    definition = '<div class="project-definition"><div><h3>'+twin('زیرساخت مشترک برای برنامه‌های AI یک تیم','Shared infrastructure for a team’s AI apps')+'</h3>'+p('توسعه‌دهنده برنامه‌اش را با مدل، prompt، ابزارهای مجاز و دادهٔ موردنیاز تعریف می‌کند. پلتفرم قرار است اجرای آن را بپذیرد، وضعیتش را نگه دارد، مدل و ابزار را فراخوانی کند و نتیجه و trace قابل‌بررسی برگرداند.','A developer defines an app with its model, prompt, permitted tools, and data. The platform is intended to accept runs, retain their state, call models and tools, and return inspectable results and traces.')+'<dl class="project-contract">'+''.join('<div><dt>'+twin(*name)+'</dt><dd>'+twin(*value)+'</dd></div>' for name,value in [
        (('کاربر اصلی','Primary user'),('توسعه‌دهندهٔ برنامهٔ AI','AI-application developer')),
        (('ورودی','Input'),('تعریف app، داده و درخواستِ اجرا','App definition, data, and a run request')),
        (('خروجی','Output'),('نتیجه، وضعیت، شواهد و trace هر run','Result, status, evidence, and a per-run trace')),
    ])+'</dl></div><div class="project-demo"><h3>'+twin('دموی پیشنهادی: چرا API کند شده؟','Proposed demo: why did the API slow down?')+'</h3>'+p('یک alert وارد می‌شود. برنامهٔ Investigator از طریق پلتفرم، deployment اخیر، metric، trace و runbook مجاز را می‌خواند.','An alert arrives. Through the platform, the Investigator app reads recent deployments, metrics, traces, and an authorized runbook.')+'<div class="demo-evidence" aria-label="Proposed evidence sources">'+''.join('<bdi>'+x+'</bdi>' for x in ['Deployments','Metrics','Traces','Runbooks'])+'</div><h4>'+twin('گزارشی که می‌خواهیم بگیریم','The report we want to receive')+'</h4>'+ul([('چه اتفاقی افتاد و به چه ترتیبی؟','What happened, and in what order?'),('کدام فرضیه با کدام شاهد سازگار است؟','Which hypothesis fits which evidence?'),('چه چیزی هنوز نامعلوم است؟','What remains uncertain?')])+p('سناریوی آزمایشگاه مصنوعی است. نتیجهٔ مستند یا «شواهد کافی نیست» هر دو می‌توانند خروجی درست باشند.','The lab scenario is synthetic. An evidence-backed result or “insufficient evidence” can both be correct outcomes.')+'</div></div>'
    problems = [
        ('Model Gateway','layer-4','هر app اتصال مدل، credential و هزینه را جدا مدیریت می‌کند.','Every app separately manages model connections, credentials, and spend.','یک مرز مشترک برای انتخاب مدل، مجوز، deadline، budget و ثبت مصرف.','A shared boundary for routing, authorization, deadlines, budgets, and usage records.'),
        ('Durable Runtime','layer-1','با crash یا timeout، اجرای چندمرحله‌ای نیمه‌کاره می‌ماند.','Crashes and timeouts interrupt multi-step runs.','وضعیت و نتیجهٔ stepها پایدار بماند؛ retry و ادامهٔ اجرا قرارداد روشن داشته باشند.','Persist step state/results and define explicit retry and resume contracts.'),
        ('Live Context','layer-0','داده عوض یا حذف می‌شود و مجوزهای قبلی ممکن است معتبر نباشند.','Data changes or is deleted, and old permissions may no longer apply.','بازیابی دادهٔ نسخه‌دار و مجاز؛ تازگی و CDC بر اساس نیاز و آزمون تصمیم‌گیری شوند.','Retrieve versioned, authorized data; justify freshness and CDC through requirements and tests.'),
        ('Evaluation & Release','layer-3','با تغییر prompt یا مدل، معلوم نیست کدام رفتار بهتر یا خراب‌تر شده.','A model or prompt change can improve some behaviors and regress others.','نسخه‌های ثابت، dataset و آزمونِ کیفیت؛ تصمیمِ انتشار بر اساس شاهد.','Pinned versions, datasets, and quality tests; evidence-based release decisions.'),
        ('AI Investigator','layer-2','برای بررسی رخداد باید شواهد چند منبع را کنار هم گذاشت.','Incident investigation requires evidence from several sources.','یک app نمونه که از قابلیت‌های مشترک استفاده می‌کند؛ بعداً app پاسخ‌گویی مستند هم همان هسته را به کار می‌گیرد.','A sample app using shared capabilities; a cited-answer app should later reuse the same core.'),
    ]
    capabilities = '<div class="project-problems"><h3>'+twin('چه مشکلی را حل می‌کنیم؟','Which problems are we solving?')+'</h3>'
    for name,color,problem_fa,problem_en,solution_fa,solution_en in problems:
        capabilities += '<article class="problem-row"><h4 class="'+color+'" lang="en" dir="ltr">'+name+'</h4><div><h5>'+twin('مسئله','Problem')+'</h5>'+p(problem_fa,problem_en)+'</div><div><h5>'+twin('مسئولیت پیشنهادی','Proposed responsibility')+'</h5>'+p(solution_fa,solution_en)+'</div></article>'
    capabilities += '</div>'
    scope = '<div class="project-scope"><div><h3>'+twin('اولین چیزی که می‌سازیم','The first thing to build')+'</h3>'+p('پیشنهاد ADR-002: یک مسیر کوچک از ثبت app و ارسال run تا یک فراخوانی مدل، یک ابزار خواندنی و دریافت نتیجه و trace. همین مسیر باید قابل‌اجرا و قابل‌آزمون با crash باشد.','ADR-002 proposes one small path: register an app, submit a run, call one model and one read-only tool, and retrieve the result and trace. Make that path runnable and test it under crashes.')+link('#ADR-002','مرز نسخهٔ اول هنوز پیشنهادی است','The first-version boundary remains proposed')+'</div><div><h3>'+twin('چیزی که بعداً اضافه می‌کنیم','What comes later')+'</h3>'+p('context زنده و CDC، ارزیابی و انتشار نسخه‌ها، چند برنامه روی هستهٔ مشترک و آزمایش serving روی GPU. پیشنهاد فعلی استفاده از مدل آماده است؛ آموزش یک مدل بنیادی از صفر در این scope نیست.','Live context and CDC, evaluation/release, multiple apps on the shared core, and GPU-serving experiments. The current proposal uses existing models; training a foundation model from scratch is outside scope.')+link('#roadmap','مسیر پیشنهادی ساخت','The proposed build track')+'</div></div>'
    careers = '<div class="project-careers"><h3>'+twin('چه چیزی برای رزومه قابل‌نشان‌دادن می‌شود؟','What would become portfolio evidence?')+'</h3>'+p('برای مسیر AI Engineer: طراحی ابزار و retrieval، ارزیابی پاسخ و تحلیل خطا. برای AI Platform Engineer: قرارداد API، دوام اجرا، کنترل دسترسی، ظرفیت، هزینه و observability. مدرکِ کار، مخزن اجرایی، demo، آزمون crash، نتیجهٔ eval و ADRهاست؛ فعلاً این صفحه دفتر طراحی آن کار است.','For AI engineering: tools, retrieval, output evaluation, and error analysis. For AI platform engineering: API contracts, durable execution, access control, capacity, cost, and observability. Evidence means working code, a demo, crash tests, eval results, and ADRs. This page is currently the design workbook.')+'</div>'
    overview = '<section id="overview" class="workshop-section project-overview"><h2>'+twin('این پروژه دقیقاً چیست؟','What exactly is this project?')+'</h2>'+p('قرار است یک پلتفرم قابل‌استفادهٔ مجدد بسازیم تا توسعه‌دهنده برنامهٔ AI خودش را روی آن اجرا و بررسی کند. Investigator اولین برنامهٔ نمونه است؛ هستهٔ پروژه، زیرساختی است که برنامه‌های دیگر هم بتوانند از آن استفاده کنند.','Build a reusable platform on which developers can run and inspect their AI applications. Investigator is the first sample app; the core is infrastructure that other applications can also use.')+definition+capabilities+scope+careers+'<div class="workshop-links">'+link('#company-evidence','این مسئله‌ها کجا مطرح شده‌اند؟','Where have these problems appeared?')+link('#start-here','حالا طراحی را شروع کنیم','Start the design workshop')+'</div></section>'

    industry = '<div class="industry-evidence"><h3>'+twin('نمونه‌های مستند در کارِ واقعی شرکت‌ها','Documented industry examples')+'</h3>'+p('این مقاله‌ها وجودِ مسئلهٔ مهندسی را نشان می‌دهند؛ مدرکِ سؤال مصاحبه نیستند. ارتباط با پروژه، برداشت آموزشی ماست.','These articles demonstrate engineering problems, not interview prompts. Their connection to this project is our educational interpretation.')
    for source in evidence['industry_sources']:
        industry += '<article><h4 lang="en" dir="ltr">'+source['company']+'</h4><div>'+p(*source['topic'])+f'<a href="{source["url"]}" target="_blank" rel="noopener">'+source['title']+'</a><span class="source-date" dir="ltr">'+source['date']+'</span></div></article>'
    industry += '</div>'
    register = '<div class="interview-register"><h3>'+twin('سؤال‌ها و بحث‌های گزارش‌شده در مصاحبه','Reported interview questions and discussions')+'</h3>'+p('۸ رکورد از ۷ شرکت: یک تمرین رسمیِ منتشرشده و هفت روایت داوطلب. عنوان‌ها خلاصه‌سازی شده‌اند، نه نقلِ کامل صورت‌سؤال. هر رکورد نقش، تاریخِ موجود، منبع و میزان ارتباط با پروژه را دارد.','Eight records across seven companies: one officially released exercise and seven candidate accounts. Titles are paraphrases, not full prompt reproductions. Each record gives role, available date, source, and scope of relevance.')
    for row in evidence['reports']:
        official = row['kind']=='official'
        label = twin('انتشار رسمی' if official else 'روایت داوطلب','Official release' if official else 'Candidate report')
        register += f'<details class="interview-record" id="{row["id"]}" data-evidence="{row["kind"]}"><summary><span class="interview-company"><bdi>'+row['company']+'</bdi><span>'+row['role']+'</span><span class="interview-question-preview">'+twin(*row['short_title'])+'</span></span><span class="evidence-kind">'+label+'</span>'+icon('plus')+'</summary><div class="interview-body"><h4>'+twin('چه چیزی گزارش شده؟','What was reported?')+'</h4>'+p(*row['question'])+'<h4>'+twin('کجای پروژه به آن مربوط است؟','Where does it connect to this project?')+'</h4>'+p(*row['mapping'])+'<p class="interview-topic-links">'+''.join(f'<a href="#{target}">{target}</a>' for target in row['anchors'])+'</p><div class="evidence-limits">'+p(*row['date_note'])+p(*row['limit'])+'</div><a class="workshop-link" href="'+row['url']+'" target="_blank" rel="noopener">'+twin('باز کردن منبع: ','Open source: ')+row['source']+icon('next')+'</a></div></details>'
    register += '</div>'
    methodology = '<details class="workbook-reference"><summary>'+twin('روش جست‌وجو و حدودِ اعتبار این فهرست','Search method and limits of this register')+icon('plus')+'</summary><div class="disclosure-body">'+p('در ۱۵ اکتبر ۲۰۲۶ جست‌وجویی گسترده با ۲۶ عبارتِ هدفمند در منابع عمومی، Reddit، LeetCode، تجربه‌های Aced/Exponent و Taro، و وبلاگ‌های مهندسی انجام شد. فهرست جامعِ کل اینترنت یا بانکِ تأییدشدهٔ سؤال‌های شرکت‌ها نیست.','On 15 October 2026, a broad search used 26 targeted queries across public sources, Reddit, LeetCode, Aced/Exponent and Taro accounts, and engineering blogs. This is neither an exhaustive internet search nor a verified company question bank.')+p('تاریخ بررسی با تاریخ مصاحبه فرق دارد؛ هرجا تاریخ دقیق نداریم، نوشته‌ایم. چند بازنشرِ یک روایت را شاهد مستقل حساب نکرده‌ایم. پست‌های تبلیغاتی و فهرست‌های بدون منبع در نتیجهٔ رسمی ادغام نشده‌اند؛ دو روایتِ دارای زمینهٔ تبلیغاتی با همان محدودیت مشخص شده‌اند.','The review date differs from the interview date; missing dates are explicit. Reposts are not independent corroboration. Promotional material and unsourced banks are not treated as official evidence; two reports with promotional context are identified accordingly.')+p('برای سؤالِ «همین پلتفرم کامل را طراحی کن» شاهد عمومی کافی پیدا نشد. این پروژه ترکیبی آموزشی است؛ شباهتِ هر بخش به یک سؤال به معنای یکسان‌بودن scope یا کفایت برای قبولی نیست.','We did not find sufficient public evidence for this exact complete-platform prompt. This is an educational synthesis; component overlap does not establish identical scope or guarantee interview success.')+'<p><a href="interview-evidence.json">'+twin('فهرست منابع و وضعیت شواهد (JSON)','Sources and evidence status (JSON)')+'</a></p></div></details>'
    companies = '<section id="company-evidence" class="workshop-section company-evidence"><h2>'+twin('در کدام شرکت‌ها چنین مسئله‌هایی مطرح شده؟','Which companies have raised related problems?')+'</h2>'+p('خودِ این پروژه را به یک شرکت نسبت نمی‌دهیم. در پایین، نمونهٔ رسمیِ کار مهندسی، تمرینِ منتشرشده و تجربهٔ گزارش‌شدهٔ مصاحبه برچسب جدا دارند. تاریخ بررسی منابع: ۱۵ اکتبر ۲۰۲۶.','We do not attribute this entire project to a company. Official engineering work, a released hiring exercise, and reported interview experiences are labeled separately below. Sources checked on 15 October 2026.')+register+industry+methodology+'<div class="workshop-links">'+link('#start-here','از شناخت پروژه به طراحی نیازها','Move from project context to requirements')+'</div></section>'
    return overview+companies
